  pokemonEncountersListResponseSuccess;

export const getPokemonEncountersListUrl = (pokemonId: string) => {
  return `https://pokeapi.co/api/v2/pokemon/${pokemonId}/encounters`;
};

/**
 * Handles Pokemon Encounters as a sub-resource.
 * @summary Get pokemon encounter
 */
export const pokemonEncountersList = async (
  pokemonId: string,
  options?: RequestInit,
): Promise<pokemonEncountersListResponse> => {
  const res = await fetch(getPokemonEncountersListUrl(pokemonId), {
    ...options,
    method: 'GET',
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: pokemonEncountersListResponse['data'] = body
    ? JSON.parse(body)
    : {};
  return {
    data,
    status: res.status,
    headers: res.headers,
  } as pokemonEncountersListResponse;
};
